<?php get_header(); get_template_part('slider'); ?><main class="entry-wrap"><div class="inner-grid"><article class="entry-card"><?php while(have_posts()):the_post(); ?><h1><?php the_title(); ?></h1><div class="news-meta"><?php echo esc_html(get_the_date('d/m/Y')); ?></div><?php if($s=pvdmcn_demo_status()): ?><div class="recovery-status">Trạng thái: <strong><?php echo esc_html($s); ?></strong></div><?php endif; ?><?php the_content(); ?><?php $src=get_post_meta(get_the_ID(),'_pvdmcn_source_urls',true); if(is_array($src)&&$src): ?><div class="source-links"><strong>Nguồn phục hồi:</strong> <?php foreach($src as $u): ?><a href="<?php echo esc_url($u); ?>" target="_blank" rel="noopener">link</a><?php endforeach; ?></div><?php endif; ?><?php endwhile; ?></article><?php get_template_part('sidebar-old'); ?></div></main><?php get_template_part('activity-strip'); get_footer(); ?>
